        { const a = 1 - p1; if (a > 0.02) { ctx.save(); ctx.globalAlpha *= a; rich(["Σxᵢ = " + nf(SUM, 2) + " · เฉลี่ย " + nf(MEAN, 2)], G1.px + G1.pw + 50 - 6, G1.py - 12, C.new, { size: 11.5, weight: 700, align: "right" }); ctx.restore(); } }
        ctx.save(); ctx.lineWidth = 1.5; ctx.setLineDash([6, 4]);
