          P.label(nf(wcTrue, 1) + " (เส้นจริง)", XW(wcTrue) - 8, YL(0) + 14, C.meas, { size: 11.5, weight: 700, align: "right" });
          /* มาตรเฟส −180° … −90° */
          const gw = Math.min(210, (x1 - x0) * 0.58), gx = x1 - 8 - gw, gy = top + 54, gh = 10;
          P.label("เฟสวงเปิดที่ ω_c (เส้นจริง)", x1 - 8, gy - 22, C.ink2, { size: 11.5, weight: 700, align: "right" });
          ctx.fillStyle = C.sunk; ctx.fillRect(gx, gy, gw, gh); ctx.strokeStyle = C.line2; ctx.lineWidth = 1; ctx.strokeRect(gx + 0.5, gy + 0.5, gw - 1, gh - 1);
