          ctx.fillStyle = C.crit; ctx.beginPath(); ctx.moveTo(mx, gy - 1); ctx.lineTo(mx - 5, gy - 9); ctx.lineTo(mx + 5, gy - 9); ctx.closePath(); ctx.fill();
