            ctx.beginPath(); ctx.moveTo(px - 8, cy - 8); ctx.lineTo(px + 8, cy + 8); ctx.moveTo(px - 8, cy + 8); ctx.lineTo(px + 8, cy - 8); ctx.stroke();
