          { const q = f(-0.707, 0.707); lab("|W| = 1", q[0] - 5, q[1] - 7, C.ink3, { size: 11.5, align: "right" }); }

          const path = pts => { ctx.beginPath(); pts.forEach((p, i) => { const q = f(p[0], p[1]); if (i) ctx.lineTo(q[0], q[1]); else ctx.moveTo(q[0], q[1]); }); };
          const fadeA = lerp(1, 0.38, prog(5));

          /* เส้นโค้ง k = 100 */
