          [1, 10, 100].forEach(d => [1, 2, 3, 4, 5, 6, 7, 8, 9].forEach(m => { const w = d * m; if (w <= 300) { const x = Math.round(xw(w)) + 0.5; ctx.moveTo(x, iy); ctx.lineTo(x, iy + ih); } }));
          ctx.stroke();
          for (let v = 0; v <= top + 1e-9; v += ys) P.label(nf(v, ydec), ix - 5, yv(v), C.ink3, { size: 10, weight: 500, align: "right", mono: true, halo: 3 });
          [1, 10, 100].forEach(w => P.label(String(w), xw(w), iy + ih + 12, C.ink3, { size: 10, weight: 500, align: "center", mono: true, halo: 3 }));
          ctx.strokeStyle = C.line2; ctx.lineWidth = 1.4; ctx.beginPath(); ctx.moveTo(ix, iy); ctx.lineTo(ix, iy + ih); ctx.lineTo(ix + iw, iy + ih); ctx.stroke();

