    const EDC = '<span class="ed">ผู้เรียบเรียงคำนวณ</span>';
    const t1s = sb("T", "1"), t2s = sb("T", "2"), tp = sb("t", "п");
    const sec = v => nf(v, 2) + " с";
    const cpx = (z, d) => nf(z[0], d) + (z[1] ? " ± j" + nf(Math.abs(z[1]), d) : "");

