    const BOXES = [BOX_A, BOX_A, BOX_A, BOX_A, BOX_A, BOX_B];
    const SW1 = Math.log(4 / OM[0]) / Math.log(OM[NP - 1] / OM[0]);                    // ขั้น 2 วาดถึง ω = 4
