          ctx.strokeStyle = C.crit; ctx.lineWidth = 1.2; ctx.setLineDash([3, 3]); ctx.beginPath(); ctx.moveTo(X(-Cc), Y(0)); ctx.lineTo(X(-Cc - Rr), Y(0)); ctx.stroke(); ctx.setLineDash([]);
