    const ED = '<span class="ed">ผู้เรียบเรียงเลือกค่า</span>', EDC = '<span class="ed">ผู้เรียบเรียงคำนวณ</span>';
    const dg = v => nf(v, 3) + "°", fs = (v, d) => nf(v, d === undefined ? 2 : d) + " 1/с";

