        [-0.15, -0.1, -0.05, 0, 0.05, 0.1, 0.15].forEach(v => P.label(v === 0 ? "0" : nf(v, 2), x0 - 5, Y(v), C.ink3, { size: 10.5, weight: 500, mono: true, align: "right", halo: 3 }));
