        ctx.strokeStyle = C.deep; ctx.lineWidth = 1.8; ctx.setLineDash([6, 4]);
        ctx.beginPath();
        ctx.moveTo(X(B), y0); ctx.lineTo(X(B), Y(-B1)); ctx.lineTo(x1, Y(-B1));
        ctx.moveTo(X(-B), y1); ctx.lineTo(X(-B), Y(B1)); ctx.lineTo(x0, Y(B1));
        ctx.stroke(); ctx.restore(); ctx.setLineDash([]);
        P.label("b", X(B) + 6, Y(0) + 11, C.deep, { size: 11.5, weight: 700, halo: 3 });
        P.label("−b", X(-B) - 6, Y(0) + 11, C.deep, { size: 11.5, weight: 700, align: "right", halo: 3 });
        P.label("b₁", X(0) + 5, Y(B1) - 8, C.deep, { size: 11.5, weight: 700, halo: 3 });
        P.label("−b₁", X(0) - 5, Y(-B1) + 8, C.deep, { size: 11.5, weight: 700, align: "right", halo: 3 });

        /* ป้ายย่าน */
        ctx.save(); ctx.globalAlpha = 0.6 + 0.4 * vis(s => s === 0 ? 1 : 0);
        P.label("M = +M₀", x1 - 5, y0 + 13, C.new, { size: 12, weight: 700, align: "right", halo: 3 });
        P.label("γ″ = −ε₀", x1 - 5, y0 + 28, C.new, { size: 11.5, weight: 600, align: "right", halo: 3 });
        P.label("M = −M₀", x0 + 5, y1 - 28, C.ref, { size: 12, weight: 700, halo: 3 });
        P.label("γ″ = +ε₀", x0 + 5, y1 - 13, C.ref, { size: 11.5, weight: 600, halo: 3 });
        P.label("M = 0", x0 + 5, y0 + 13, C.ink2, { size: 11.5, weight: 700, halo: 3 });
        P.label("γ″ = 0", x0 + 5, y0 + 28, C.ink3, { size: 11, weight: 600, halo: 3 });
        P.label("M = 0", x1 - 5, y1 - 28, C.ink2, { size: 11.5, weight: 700, align: "right", halo: 3 });
